    n = variables(size)
    objectives = front_objectives(problem_name, size)
    ref_dirs = get_reference_directions("das-dennis", objectives, n_partitions=divisions)

    def mutation():
        return PM(eta=20, prob_var=1.0 / n)

    def sbx():
        return SBX(prob=0.9, eta=15)

